def mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    result = []
    ordering_map = {}
    for ordering in orderings:
        for item in ordering:
            if item not in ordering_map:
                ordering_map[item] = [ordering]
            else:
                ordering_map[item].append(ordering)
    for item, orderings in ordering_map.items():
        if len(orderings) == 1:
            result.append(item)
        else:
            result.append(orderings[0][orderings[0].index(item):])
    return result

