def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Sort the list of classes based on their inheritance hierarchy
    classes.sort(key=lambda x: x.mro())
    # Create a set to store the minimal resulting list of bases
    minimal_bases = set()
    # Iterate through the list of classes and check for duplicates
    for cls in classes:
        # If the class is not in the set, add it to the set
        if cls not in minimal_bases:
            # Add the class to the set and recursively add its base classes
            minimal_bases.add(cls)
            for base in cls.mro()[1:]:
                minimal_bases.add(base)
    # Return the sorted list of minimal bases
    return sorted(minimal_bases, key=lambda x: x.mro())

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
