def format(sql, params):
    # Check if the input parameters are of the correct type
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes")
    if not isinstance(params, (dict, list)):
        raise TypeError("params must be a dictionary or list")

    # Convert the input parameters to the out-style format
    if isinstance(params, dict):
        out_params = {f"{key}": value for key, value in params.items()}
    else:
        out_params = [value for value in params]

    # Return the formatted SQL query and the converted out-style parameters
    return (sql, out_params)

def format(self, sql, params):
    if isinstance(params, dict):
        # If params is a dict, we use it as it is
        out_params = dict()
        for key, value in params.items():
            if isinstance(key, int):
                out_params[f"@p{key}"] = value
            else:
                out_params[f":{key}"] = value
    elif isinstance(params, list):
        # If params is a list, we use it as it is
        out_params = list()
        for i, value in enumerate(params):
            out_params.append(f"@p{i}")
    else:
        raise ValueError("params must be a dict or a list")

    # Replace the in-style parameters with the out-style parameters
    for key in out_params:
        sql = sql.replace(key, out_params[key])

    return (sql, params)

def format(self, sql, params):
    """
    Converts the SQL query to use the out-style parameters instead of the in-style parameters
    """
    # Check if params is a dict or a list
    if isinstance(params, dict):
        # Create a new dict to store the converted out-style parameters
        out_params = {}
        # Iterate over the keys in params
        for key in params:
            # Check if the key is a str
            if isinstance(key, str):
                # Add the key to the out_params dictionary with the value from params
                out_params[key] = params[key]
            # Check if the key is an int
            elif isinstance(key, int):
                # Add the key to out_params with the value from params using the key as the index
                out_params[key] = params[key]
        # Return the formatted SQL query and the out_params dictionary
        return (sql, out_params)
    # If params is a list
    elif isinstance(params, list):
        # Create a new list to store the converted out-style parameters
        out_params = []
        # Iterate over the items in params
        for param in params:
            out_params.append(param)
        # Return the formatted SQL query and the out_params list
        return (sql, tuple(out_params))
    # If params is not a dict or a list, raise a ValueError
    else:
        raise ValueError("Invalid type for params: expected dict or list, got %s" % type(params))

