def validate_fixity(self, fixity, manifest_files):
    # Check if the fixity block is present in the inventory
    if 'fixity' not in self.inventory:
        return

    # Get the list of files and check if all are present in the manifest
    fixity_files = self.inventory['fixity'].keys()
    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError(f'File {file} listed in fixity block but not in manifest')

    # Check if the checksums match for all files
    for file in fixity_files:
        if self.inventory['fixity'][file]['checksum'] != manifest_files[file]['checksum']:
            raise ValueError(f'Checksum for file {file} does not match in fixity block and manifest')

    # Check if the last modified date matches for all files
    for file in fixity_files:
        if self.inventory['fixity'][file]['last_modified'] != manifest_files[file]['last_modified']:
            raise ValueError(f'Last modified date for file {file} does not match in fixity block and manifest')

