    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    result = []

    for expr in args:
        if expr.is_and():
            left, right = expr.args
            if left.is_or() and left.args[0] == expr:
                result.append(left)
            elif right.is_or() and right.args[0] == expr:
                result.append(right)
            else:
                result.append(expr)
        elif expr.is_or():
            left, right = expr.args
            if left.is_and() and left.args[0] == expr:
                result.append(left)
            elif right.is_and() and right.args[0] == expr:
                result.append(right)
            else:
                result.append(expr)
        else:
            result.append(expr)

    return result

