        version_inventory_path = f'{version_dir}/inventory.json'
        if not os.path.exists(version_inventory_path):
            raise Exception(f'Version {version_dir} inventory does not exist.')

        with open(version_inventory_path, 'r') as inventory_file:
            version_inventory = json.load(inventory_file)

        if 'content_digests' not in version_inventory:
            raise Exception(f'Version {version_dir} inventory does not have content digests.')

        for content_digest in version_inventory['content_digests']:
