def get_repo_archive(url: str, destination_path: Path) -> Path:
    response = requests.get(url)
    with tarfile.open(fileobj=BytesIO(response.content), mode="r|*") as tar:
        tar.extractall(destination_path)

    # Find the 'desc' file and return the path to it
    for member in tar.getmembers():
        if member.isfile() and member.name.endswith('.desc'):
            desc_path = os.path.join(destination_path, member.name)
            return Path(desc_path)

    # If no 'desc' file is found, an error will be raised
    raise ValueError("'desc' file not found in archive")

