        if is_posix():
            platform = 1
        else:
            platform = 0

    if platform == 1:
        shlex_split = shlex.split(s, posix=True)
    elif platform == 0:
        shlex_split = shlex.split(s, posix=False)
    else:
        raise ValueError(f"Invalid platform value: {platform}")

    return shlex_split

