    time_parts = time_part.split(":")
    if len(time_parts) > 0:
        time_values["hour"] = int(time_parts[0])
    if len(time_parts) > 1:
        time_values["minute"] = int(time_parts[1])
    if len(time_parts) > 2:
        time_values["second"] = int(time_parts[2])
    if len(time_parts) > 3:
        time_values["microsecond"] = int(time_parts[3][:6])

    # Build datetime object
    dt = datetime.datetime(**date_values, **time_values)

    # Apply time zone offset
    if tz_offset:
        tz_offset_values = {}
        tz_offset_values["hours"] = int(tz_offset[:2])
        tz_offset_values["minutes"] = int(tz_offset[2:])
        dt = dt.replace(tzinfo=dateutil.tz.tzoffset(tz_offset, **tz_offset_values))

    return dt

