    def replace_links(match):
        url = match.group(1)
        if not url.startswith("http"):
            url = "http://" + url
        return "<a href='{}'>{}</a>".format(url, url)

    text = re.sub(r"(?i)\b((?:https?://|www\d{0,3}[.]|[a-z0-9.\-]+[.][a-z]{2,4}/)(?:[^\s()<>]+|\(([^\s()<>]+|(\([^\s()<>]+\)))*\))+(?:\(([^\s()<>]+|(\([^\s()<>]+\)))*\)|[^\s`!()\[\]{};:'\".,<>?“”‘’]))", replace_links, text)
    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    for match in re.finditer(r'\[([^\]]*)\]\(([^\)]*)\)', text):
        match_id = match.group(1)
        match_url = match.group(2)
        if match_id == '':
            match_id = match_url
        text = text.replace(match[0], '<a href="{match_url}" id="{match_id}">{match_id}</a>'.format(match_url=match_url, match_id=match_id))
    return text

